-- public.plant_refusal(p_world uuid, p_kind text, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.plant_refusal(p_world uuid, p_kind text, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_name text := water_plant_word(p_kind); v_depth double precision; v_kind text;
begin
  if not in_bounds(p_world, p_x, p_y) then return 'There is nothing there.'; end if;
  if under_building(p_world, p_x, p_y) is not null then return under_building(p_world, p_x, p_y); end if;
  if not has_water(p_world, p_x, p_y) then
    return upper(left(v_name, 1)) || substr(v_name, 2) || ': needs still water (pond, pool or sea shallows).';
  end if;
  if water_runs(p_world, p_x, p_y) then return upper(left(v_name, 1)) || substr(v_name, 2) || ': needs still water, not running.'; end if;
  v_depth := water_depth(p_world, p_x, p_y);
  if v_depth < water_plant_shallowest() or v_depth > water_plant_deepest() then
    return upper(left(v_name, 1)) || substr(v_name, 2) || ': needs water ' || metres(water_plant_shallowest())
        || ' to ' || metres(water_plant_deepest()) || ' m deep.';
  end if;
  if land_tile(p_world, p_x, p_y) = tile_id('Stepping stones') then return 'Stepping stones here.'; end if;
  select w.kind into v_kind from water_plant w where w.world_id = p_world and w.x = p_x and w.y = p_y;
  if v_kind is not null then return 'Already planted: ' || water_plant_word(v_kind) || '.'; end if;
  return null;
end $function$
